package com.example.inventory; import java.util.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/inventory") public class InventoryController { @PostMapping("/reserve") public Map<String,String> reserve(@RequestBody Map<String,Object> r){if(Boolean.TRUE.equals(r.get("forceFail"))) throw new IllegalStateException("Out of stock"); return Map.of("reservationId",UUID.randomUUID().toString(),"status","RESERVED");} @PostMapping("/release") public Map<String,String> release(){return Map.of("status","RELEASED");} }
